import { autoJsStoreUtils, Window, WindowConf } from '@droid/android';
import { toProxy, watchUpdates } from '@fanfanlo';

const STORE_KEY_WINDOW_DATA = 'android_float_window_data';

// 正则表达式常量
const URL_REGEX = /^(https?:\/\/|ftp:\/\/|\/\/)[^\s]+$/i;
const HTML_REGEX = /<[^>]+>/;

export interface IAndroidFloatWindowItem {
  // 用户可编辑的属性
  tag: string; // 唯一标识符（窗口名称，用于打开/关闭）
  contentUrl: string; // URL或HTML内容
  width: number; // 窗口宽度（像素，默认0，不能为负数）
  height: number; // 窗口高度（像素，默认0，不能为负数）

  // 系统属性（自动填写，用户不可编辑）
  createdAt?: number; // 创建时间（时间戳）
  updatedAt?: number; // 更新时间（时间戳）
}

export interface IFloatWindowStore {
  windowList: WindowConf[];
}

export interface IWindowData {
  windowData: IFloatWindowStore;
  initialized: boolean;
}

const data = toProxy<IWindowData>({
  windowData: {
    windowList: [],
  },
  initialized: false,
});

/**
 * 检测 contentUrl 是 URL 还是 HTML
 * @param content 输入内容
 * @returns 'url' | 'html' | 'invalid'
 */
export function detectContentType(content: string): 'url' | 'html' | 'invalid' {
  if (!content || content.trim().length === 0) {
    return 'invalid';
  }

  // 先检测是否包含 HTML 标签
  if (HTML_REGEX.test(content)) {
    return 'html';
  }

  // 检测是否为有效 URL
  if (URL_REGEX.test(content.trim())) {
    return 'url';
  }

  return 'invalid';
}

/**
 * 验证 contentUrl 是否有效（URL 或 HTML）
 * @param content 输入内容
 * @returns boolean
 */
export function isValidContent(content: string): boolean {
  const type = detectContentType(content);
  return type !== 'invalid';
}

/**
 * 生成默认窗口名称（当前时间戳）
 * @returns 格式为 yyyy-MM-dd HH:mm:ss 的时间字符串
 */
export function generateDefaultWindowName(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const date = String(now.getDate()).padStart(2, '0');
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  const seconds = String(now.getSeconds()).padStart(2, '0');

  return `${year}-${month}-${date} ${hours}:${minutes}:${seconds}`;
}

/**
 * 检查窗口名称（tag）是否已存在
 * @param tag 要检查的 tag
 * @param excludeWindowId 排除的 windowId（用于编辑时排除自己）
 * @returns boolean true 表示已存在
 */
export function isTagExists(tag: string, excludeWindowId?: string): boolean {
  const trimmedTag = tag.trim();
  if (!trimmedTag) return false;

  return data.windowData.windowList.some(
    win => win.tag === trimmedTag && win.windowId !== excludeWindowId
  );
}
function init() {
  if (data.initialized) return;
  data.windowData = autoJsStoreUtils.read<IFloatWindowStore>(STORE_KEY_WINDOW_DATA, {
    windowList: [],
  });

  watchUpdates(data.windowData, () => {
    console.log('Detected changes in windowData, saving to storage...', data.windowData);
    autoJsStoreUtils.write(STORE_KEY_WINDOW_DATA, data.windowData);
  });
  console.log('Android Float Window data initialized:', data.windowData);
  data.initialized = true;
}

function getItemId(item: WindowConf): string {
  return `${item.windowId}`;
}



function getDismissEventType(item: WindowConf): String {
  return `window-${getItemId(item)}-dismiss`;
}
function getOpenedEventType(item: WindowConf): String {
  return `window-${getItemId(item)}-opened`;
}
function getHideEventType(item: WindowConf): String {
  return `window-${getItemId(item)}-hide`;
}
export const androidFloatWindowData = {
  data,
  init,
  getItemId: getItemId,
  getDismissEventType,
  getOpenedEventType,
  getHideEventType
};
